 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like, ne } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizationRetiredSlugs, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const ORG_SLUG_HOLD_MS = ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000;

/** True while a slug retired at `retiredAt` is still held against reassignment. */
function isHoldActive(retiredAt: string, reference: number = Date.now()): boolean {
  return reference < new Date(retiredAt).getTime() + ORG_SLUG_HOLD_MS;
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Resolves a slug to the workspace it currently names, or — while it is
 * still on hold after a rename — the workspace it used to name. The single
 * chokepoint every slug-to-workspace lookup (the session layer included) goes
 * through, so the hold behaves the same way everywhere.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retirements = getDb()
    .select({
      orgId: organizationRetiredSlugs.orgId,
      retiredAt: organizationRetiredSlugs.retiredAt,
    })
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .all();

  const held = retirements.find((retirement) => isHoldActive(retirement.retiredAt));
  if (!held) return null;

  const org = await findOrgById(brandId<OrgId>(held.orgId));
  return org && org.archivedAt === null ? org : null;
}

/**
 * Whether `slug` may become `orgId`'s slug: nothing else currently holds it
 * as its live-or-deleted current slug, and no other workspace holds it
 * retired. A workspace's own retired slugs are always available to it again.
 */
export async function isSlugAvailableForOrg(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const holder = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (holder) return false;

  const retirements = getDb()
    .select({
      orgId: organizationRetiredSlugs.orgId,
      retiredAt: organizationRetiredSlugs.retiredAt,
    })
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .all();

  return retirements.every(
    (retirement) => retirement.orgId === orgId || !isHoldActive(retirement.retiredAt),
  );
}

/**
 * Changes `orgId`'s current slug to `slug` and retires the one it replaces.
 * If `slug` was itself a slug this workspace had previously retired, that
 * retirement ends — renaming back to a held slug reclaims it outright.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  const db = getDb();
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const stamp = toIsoTimestamp(new Date());

  db.delete(organizationRetiredSlugs)
    .where(
      and(
        eq(organizationRetiredSlugs.orgId, orgId),
        eq(organizationRetiredSlugs.slug, slug),
      ),
    )
    .run();

  const row = db
    .update(organizations)
    .set({ slug, updatedAt: stamp })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  db.insert(organizationRetiredSlugs)
    .values({ id: newId(), orgId, slug: current.slug, retiredAt: stamp })
    .run();

  return toOrganization(row);
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

/**
 * Settings and profile patch. `slug` is accepted for the "change workspace
 * URL" form: the form validates the slug with `slugSchema` before it gets
 * here, so the column is written as given.
 */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput & { readonly slug?: string },
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.slug === undefined ? {} : { slug: patch.slug }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}

