/**
 * Changes a workspace's URL slug. A rename to the current slug is a no-op:
 * nothing changes and nothing publishes. Otherwise the target slug must be
 * available — not any other workspace's current slug, live or deleted, and
 * not held by another workspace's still-retiring rename — or the rename is
 * refused outright; Taskflow never suffixes its way around a collision here,
 * that is only for slugs it derives at creation.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) {
    return org;
  }

  const available = await orgRepo.isSlugAvailableForOrg(input.slug, input.orgId);
  if (!available) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const updated = await orgRepo.renameOrgSlug(input.orgId, input.slug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: org.slug,
    to: updated.slug,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
