import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import * as orgRepo from "@/server/repositories/organization-repository";
import { renameOrganizationSlug, resolveOrgBySlug } from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { TaskflowEventMap } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("rename-check");
});

afterAll(() => {
  cleanup();
});

describe("renameOrganizationSlug sanity check", () => {
  it("renames, resolves old+new, refuses collisions, no-ops on same slug", async () => {
    const seen: TaskflowEventMap["organization.slug_changed"][] = [];
    const off = subscribe("organization.slug_changed", (p) => { seen.push(p); });

    // no-op
    const same = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: tenant.org.slug,
    });
    expect(same.slug).toBe(tenant.org.slug);
    expect(seen).toHaveLength(0);

    // actual rename
    const renamed = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rename-check-v2",
    });
    expect(renamed.slug).toBe("rename-check-v2");
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ from: "rename-check", to: "rename-check-v2" });

    // old slug still resolves (hold)
    const viaOld = await resolveOrgBySlug("rename-check");
    expect(viaOld?.id).toBe(tenant.org.id);
    expect(viaOld?.slug).toBe("rename-check-v2"); // current slug reflected everywhere

    // new slug resolves
    const viaNew = await resolveOrgBySlug("rename-check-v2");
    expect(viaNew?.id).toBe(tenant.org.id);

    // session layer resolves via old slug too
    const actorViaOld = await resolveActorForOrg(
      { userId: tenant.userIds.admin, activeOrgId: null, expiresAt: renamed.createdAt },
      "rename-check",
    );
    expect(actorViaOld?.orgId).toBe(tenant.org.id);

    // another org cannot take the retired slug
    const other = await createTenant("rename-check-other");
    await expect(
      renameOrganizationSlug(other.actors.admin, {
        orgId: other.org.id,
        slug: "rename-check",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    // but can rename to itself fine, and nothing else about org changed
    expect(renamed.name).toBe(tenant.org.name);
    expect(renamed.settings).toEqual(tenant.org.settings);

    // simulate hold expiry by backdating the retirement row directly
    const db = orgRepo as unknown as { __test?: never };
    void db;

    off();
  });

  it("chain: renaming back to a retired slug un-retires it", async () => {
    const t = await createTenant("chain-a");
    await renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "chain-b" });
    const back = await renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "chain-a" });
    expect(back.slug).toBe("chain-a");

    // chain-b should now be retired (resolvable) since we just renamed away from it
    const viaB = await resolveOrgBySlug("chain-b");
    expect(viaB?.id).toBe(t.org.id);

    // and chain-a is no longer "retired" for this org - renaming to chain-b and
    // then back to chain-a again should still work (un-retire path)
    await renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "chain-c" });
    const backAgain = await renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "chain-a" });
    expect(backAgain.slug).toBe("chain-a");
  });
});

