import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { getDb, organizationRetiredSlugs } from "@/server/db";
import { renameOrganizationSlug, resolveOrgBySlug } from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("release-check");
});

afterAll(() => {
  cleanup();
});

describe("hold release", () => {
  it("stops resolving and frees the slug once the hold window has passed", async () => {
    await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "release-check-v2",
    });

    // backdate the retirement row past the 30-day hold
    const old = new Date(Date.now() - 31 * 24 * 60 * 60 * 1000).toISOString();
    getDb()
      .update(organizationRetiredSlugs)
      .set({ retiredAt: old })
      .run();

    const resolved = await resolveOrgBySlug("release-check");
    expect(resolved).toBeNull();

    const other = await createTenant("release-check-other");
    const renamed = await renameOrganizationSlug(other.actors.admin, {
      orgId: other.org.id,
      slug: "release-check",
    });
    expect(renamed.slug).toBe("release-check");
  });
});

